import gurobipy as gp
from gurobipy import GRB

def main():
    # Sets
    P = ['I', 'II', 'III']
    T = [1, 2, 3, 4]

    # Parameters
    D = {
        'I':   {1: 1500, 2: 1000, 3: 2000, 4: 1200},
        'II':  {1: 1500, 2: 1500, 3: 1200, 4: 1500},
        'III': {1: 1000, 2: 2000, 3: 1500, 4: 2500}
    }
    h = {'I': 2, 'II': 4, 'III': 3}
    H = {t: 15000 for t in T}
    c_inv = 5
    c_comp = {'I': 20, 'II': 20, 'III': 10}
    I0 = {p: 0 for p in P}
    I_final = {p: 150 for p in P}

    # Model
    model = gp.Model(env=env)

    # Decision variables
    P_var = {}
    I_var = {}
    S_var = {}
    for p in P:
        for t in T:
            P_var[(p, t)] = model.addVar(vtype=GRB.CONTINUOUS, name=f"P_{p}_{t}")
            I_var[(p, t)] = model.addVar(vtype=GRB.CONTINUOUS, name=f"I_{p}_{t}")
            S_var[(p, t)] = model.addVar(vtype=GRB.CONTINUOUS, name=f"S_{p}_{t}")

    # Constraints
    # 1. Production‑hour limit
    for t in T:
        expr = gp.LinExpr()
        for p in P:
            expr += h[p] * P_var[(p, t)]
        model.addConstr(expr <= H[t], name=f"HourLimit_t{t}")

    # 2. Product‑I production restriction
    model.addConstr(P_var[('I', 2)] == 0, name="ProdI_2")

    # 3. Inventory balance
    for p in P:
        for t in T:
            prev = I0[p] if t == 1 else I_var[(p, t - 1)]
            model.addConstr(
                I_var[(p, t)] == prev + P_var[(p, t)] - D[p][t] + S_var[(p, t)],
                name=f"InvBal_{p}_{t}"
            )

    # 5. Final inventory requirement
    for p in P:
        model.addConstr(I_var[(p, 4)] >= I_final[p], name=f"FinalInv_{p}")

    # Objective
    obj = gp.LinExpr()
    for p in P:
        for t in T:
            obj += c_inv * I_var[(p, t)] + c_comp[p] * S_var[(p, t)]
    model.setObjective(obj, GRB.MINIMIZE)

    # Solve
    model.optimize()

    # Output
    if model.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.objVal}")

if __name__ == "__main__":
    main()
