from gurobipy import GRB

def main():
    # Sets
    J = [1, 2, 3, 4, 5]          # batches
    M = [1, 2, 3]                # vats

    # Processing times p_{ij}
    p = {
        (1, 1): 3,   (1, 2): 1,   (1, 3): 1,
        (2, 1): 2,   (2, 2): 1.5, (2, 3): 1,
        (3, 1): 3,   (3, 2): 1.2, (3, 3): 1.3,
        (4, 1): 2,   (4, 2): 2,   (4, 3): 2,
        (5, 1): 2.1, (5, 2): 2,   (5, 3): 3
    }

    # Big-M constant
    M_big = sum(p[i, j] for i in J for j in M)

    # Create model with the provided environment
    model = gp.Model(env=env)

    # Decision variables
    S = {}
    C = {}
    for i in J:
        for j in M:
            S[i, j] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"S_{i}_{j}")
            C[i, j] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"C_{i}_{j}")

    y = {}
    for i in J:
        for k in J:
            if i != k:
                for j in M:
                    y[i, k, j] = model.addVar(vtype=GRB.BINARY, name=f"y_{i}_{k}_{j}")

    Cmax = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name="Cmax")

    # Constraints
    # 1. Processing on the first vat
    for i in J:
        model.addConstr(C[i, 1] == S[i, 1] + p[i, 1])

    # 2. Sequential processing on subsequent vats
    for i in J:
        for j in [2, 3]:
            model.addConstr(S[i, j] >= C[i, j - 1])
            model.addConstr(C[i, j] == S[i, j] + p[i, j])

    # 3. Mutual exclusion on each vat
    for i in J:
        for k in J:
            if i != k:
                for j in M:
                    model.addConstr(C[i, j] <= C[k, j] + M_big * (1 - y[i, k, j]))
                    model.addConstr(C[k, j] <= C[i, j] + M_big * y[i, k, j])

    for i in J:
        for k in J:
            if i < k:
                for j in M:
                    model.addConstr(y[i, k, j] + y[k, i, j] == 1)

    # 4. Makespan definition
    for i in J:
        model.addConstr(Cmax >= C[i, 3])

    # Objective
    model.setObjective(Cmax, GRB.MINIMIZE)

    # Solve
    model.optimize()

    # Output the optimal objective if found
    if model.Status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.ObjVal}")

if __name__ == "__main__":
    main()
