import gurobipy as gp
from gurobipy import GRB

def main():
    env = gp.Env()
    model = gp.Model(env=env)

    # Sets
    S = [1, 2, 3, 4, 5, 6]
    P = [1, 2, 3, 4, 5, 6]

    # Parameters
    R = {1: 10, 2: 15, 3: 25, 4: 20, 5: 18, 6: 12}
    C_R = 80   # cost per regular shift
    C_C = 120  # cost per contract shift

    # Coverage matrix a[p][s]
    a = {}
    for p in P:
        a[p] = {}
        for s in S:
            if p == s or p == ((s % 6) + 1):
                a[p][s] = 1
            else:
                a[p][s] = 0

    # Decision variables
    x_R = {}
    x_C = {}
    for s in S:
        x_R[s] = model.addVar(vtype=GRB.INTEGER, lb=0, name=f"x_R_{s}")
        x_C[s] = model.addVar(vtype=GRB.INTEGER, lb=0, name=f"x_C_{s}")

    model.update()

    # Coverage constraints
    for p in P:
        expr = gp.LinExpr()
        for s in S:
            expr += a[p][s] * (x_R[s] + x_C[s])
        model.addConstr(expr >= R[p], name=f"cover_{p}")

    # Objective: minimize total cost
    obj = gp.LinExpr()
    for s in S:
        obj += C_R * x_R[s] + C_C * x_C[s]
    model.setObjective(obj, GRB.MINIMIZE)

    # Solve
    model.optimize()

    # Output the objective value if optimal
    if model.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={int(round(model.objVal))}")

if __name__ == "__main__":
    main()
