from gurobipy import GRB

def main():
    # The environment is provided at runtime
    model = gp.Model(env=env)

    # Parameters
    labor = {'H': 17, 'M': 10, 'L': 2}
    inspect = {'H': 8, 'M': 4, 'L': 2}
    profit = {'H': 300, 'M': 200, 'L': 100}
    demand = {'H': 50, 'M': 80, 'L': 150}
    L_total = 1000
    I_total = 500

    # Decision variables
    x = {}
    for t in ['H', 'M', 'L']:
        x[t] = model.addVar(vtype=GRB.INTEGER, lb=0, name=f"x_{t}")
    model.update()

    # Objective
    model.setObjective(
        gp.quicksum(profit[t] * x[t] for t in ['H', 'M', 'L']),
        GRB.MAXIMIZE
    )

    # Constraints
    model.addConstr(
        gp.quicksum(labor[t] * x[t] for t in ['H', 'M', 'L']) <= L_total,
        name="labor_capacity"
    )
    model.addConstr(
        gp.quicksum(inspect[t] * x[t] for t in ['H', 'M', 'L']) <= I_total,
        name="inspect_capacity"
    )
    for t in ['H', 'M', 'L']:
