import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

# Distance matrix
d = {
    (1, 2): 10, (1, 3): 20, (1, 4): 12,
    (2, 1): 10, (2, 3): 5,  (2, 4): 10,
    (3, 1): 20, (3, 2): 5,  (3, 4): 8,
    (4, 1): 15, (4, 2): 12, (4, 3): 8
}

C = [1, 2, 3, 4]

# Decision variables
x = {}
for i in C:
    for j in C:
        if i != j:
            x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

u = {}
for i in [2, 3, 4]:
    u[i] = model.addVar(lb=2, ub=4, vtype=GRB.INTEGER, name=f"u_{i}")

# Out-degree constraints
for i in C:
    model.addConstr(gp.quicksum(x[i, j] for j in C if j != i) == 1, name=f"out_{i}")

# In-degree constraints
for j in C:
    model.addConstr(gp.quicksum(x[i, j] for i in C if i != j) == 1, name=f"in_{j}")

# Subtour elimination (MTZ)
for i in [2, 3, 4]:
    for j in [2, 3, 4]:
        if i != j:
            model.addConstr(u[i] - u[j] + 4 * x[i, j] <= 3, name=f"mtz_{i}_{j}")

# Objective
model.setObjective(
    gp.quicksum(d[i, j] * x[i, j] for i in C for j in C if i != j),
    GRB.MINIMIZE
)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
