import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

# Parameters
a = {1: 250, 2: 350, 3: 800, 4: 400, 5: 500}
min_i = {1: 1, 2: 1, 3: 1, 4: 0, 5: 1}
max_i = {1: 3, 2: 2, 3: 3, 4: 2, 5: 3}
r = 0.2

# Sets K_i
K = {
    1: [1, 2, 3],
    2: [1, 2],
    3: [1, 2, 3],
    4: [0, 1, 2],
    5: [1, 2, 3]
}

# Profit per store p_{i,k}
p = {}
p.update({(1, 1): 9, (1, 2): 8, (1, 3): 7})
p.update({(2, 1): 10, (2, 2): 9})
p.update({(3, 1): 27, (3, 2): 21, (3, 3): 20})
p.update({(4, 1): 16, (4, 2): 10})
p.update({(5, 1): 17, (5, 2): 15, (5, 3): 12})
# Default profit for missing k (e.g., k=0) is 0
def profit(i, k):
    return p.get((i, k), 0)

# Decision variables y_{i,k}
y = {}
for i in a:
    for k in K[i]:
        y[i, k] = model.addVar(vtype=GRB.BINARY, name=f"y_{i}_{k}")

# Derived integer variables x_i
x = {}
for i in a:
    x[i] = model.addVar(lb=min_i[i], ub=max_i[i], vtype=GRB.INTEGER, name=f"x_{i}")

# Constraints
# Exactly one choice per store type
for i in a:
    model.addConstr(gp.quicksum(y[i, k] for k in K[i]) == 1, name=f"choice_{i}")

# Definition of x_i
for i in a:
    model.addConstr(x[i] == gp.quicksum(k * y[i, k] for k in K[i]), name=f"def_x_{i}")

# Area capacity
model.addConstr(gp.quicksum(a[i] * x[i] for i in a) <= 5000, name="area_capacity")

# Objective
obj_expr = gp.quicksum(k * profit(i, k) * y[i, k] for i in a for k in K[i])
model.setObjective(r * obj_expr, GRB.MAXIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
```

